        final String[] queries = new String[] { "SELECT UPS(name) AS UP FROM CANNED_DATA WHERE name NOT LIKE '% %'", "SELECT UPS_METHOD(name) AS UP FROM CANNED_DATA WHERE name NOT LIKE '% %'" };
