@Test
public void testReplaceRegexEscapedQuotes() {
    final List<RecordField> fields = new ArrayList<>();
    fields.add(new RecordField("id", RecordFieldType.INT.getDataType()));
    fields.add(new RecordField("name", RecordFieldType.STRING.getDataType()));
    final RecordSchema schema = new SimpleRecordSchema(fields);
    final Map<String, Object> values = new HashMap<>();
    values.put("id", 48);
    final Record record = new MapRecord(schema, values);
    // Quotes
    // NOTE: At Java code, a single back-slash needs to be escaped with another-back slash, but needn't do so at NiFi UI.
    //       The test record path is equivalent to replaceRegex(/name, '\'', '"')
    values.put("name", "'John' 'Doe'");
    assertEquals("\"John\" \"Doe\"", RecordPath.compile("replaceRegex(/name, '\\'', '\"')").evaluate(record).getSelectedFields().findFirst().get().getValue(), "Replacing quote to double-quote");
    values.put("name", "\"John\" \"Doe\"");
    assertEquals("'John' 'Doe'", RecordPath.compile("replaceRegex(/name, '\"', '\\'')").evaluate(record).getSelectedFields().findFirst().get().getValue(), "Replacing double-quote to single-quote");
