    assertEquals("\"John\" \"Doe\"", RecordPath.compile("replaceRegex(/name, \"'\", \"\\\"\")").evaluate(record).getSelectedFields().findFirst().get().getValue(), "Replacing quote to double-quote, the function arguments are wrapped by double-quote");
    values.put("name", "\"John\" \"Doe\"");
    assertEquals("'John' 'Doe'", RecordPath.compile("replaceRegex(/name, \"\\\"\", \"'\")").evaluate(record).getSelectedFields().findFirst().get().getValue(), "Replacing double-quote to single-quote, the function arguments are wrapped by double-quote");
}

