    //       The test record path is equivalent to replaceRegex(/name, '\\', '/')
    values.put("name", "John\\Doe");
    assertEquals("John/Doe", RecordPath.compile("replaceRegex(/name, '\\\\', '/')").evaluate(record).getSelectedFields().findFirst().get().getValue(), "Replacing a back-slash to forward-slash");
    values.put("name", "John/Doe");
    assertEquals("John\\Doe", RecordPath.compile("replaceRegex(/name, '/', '\\\\')").evaluate(record).getSelectedFields().findFirst().get().getValue(), "Replacing a forward-slash to back-slash");
}

