@Test
public void testBase64Encode() {
    final List<RecordField> fields = new ArrayList<>();
    fields.add(new RecordField("firstName", RecordFieldType.STRING.getDataType()));
    fields.add(new RecordField("lastName", RecordFieldType.STRING.getDataType()));
    fields.add(new RecordField("b", RecordFieldType.ARRAY.getArrayDataType(RecordFieldType.BYTE.getDataType())));
    final RecordSchema schema = new SimpleRecordSchema(fields);
    final List<Object> expectedValues = Arrays.asList(Base64.getEncoder().encodeToString("John".getBytes(StandardCharsets.UTF_8)), Base64.getEncoder().encodeToString("Doe".getBytes(StandardCharsets.UTF_8)), Base64.getEncoder().encode("xyz".getBytes(StandardCharsets.UTF_8)));
    final Map<String, Object> values = new HashMap<>();
    values.put("firstName", "John");
    values.put("lastName", "Doe");
    values.put("b", "xyz".getBytes(StandardCharsets.UTF_8));
    final Record record = new MapRecord(schema, values);
    assertEquals(Base64.getEncoder().encodeToString("John".getBytes(StandardCharsets.UTF_8)), RecordPath.compile("base64Encode(/firstName)").evaluate(record).getSelectedFields().findFirst().get().getValue());
    assertEquals(Base64.getEncoder().encodeToString("Doe".getBytes(StandardCharsets.UTF_8)), RecordPath.compile("base64Encode(/lastName)").evaluate(record).getSelectedFields().findFirst().get().getValue());
    assertArrayEquals(Base64.getEncoder().encode("xyz".getBytes(StandardCharsets.UTF_8)), (byte[]) RecordPath.compile("base64Encode(/b)").evaluate(record).getSelectedFields().findFirst().get().getValue());
    List<Object> actualValues = RecordPath.compile("base64Encode(/*)").evaluate(record).getSelectedFields().map(FieldValue::getValue).collect(Collectors.toList());
    IntStream.range(0, 3).forEach(i -> {
        Object expectedObject = expectedValues.get(i);
        Object actualObject = actualValues.get(i);
        if (actualObject instanceof String) {
            assertEquals(expectedObject, actualObject);
        } else if (actualObject instanceof byte[]) {
            assertArrayEquals((byte[]) expectedObject, (byte[]) actualObject);
        }
    });
}

