@Test
public void testUnescapeJson() {
    final RecordSchema address = new SimpleRecordSchema(Collections.singletonList(new RecordField("address_1", RecordFieldType.STRING.getDataType())));
    final RecordSchema person = new SimpleRecordSchema(Arrays.asList(new RecordField("firstName", RecordFieldType.STRING.getDataType()), new RecordField("age", RecordFieldType.INT.getDataType()), new RecordField("nicknames", RecordFieldType.ARRAY.getArrayDataType(RecordFieldType.STRING.getDataType())), new RecordField("addresses", RecordFieldType.CHOICE.getChoiceDataType(RecordFieldType.ARRAY.getArrayDataType(RecordFieldType.RECORD.getRecordDataType(address)), RecordFieldType.RECORD.getRecordDataType(address)))));
    final RecordSchema schema = new SimpleRecordSchema(Arrays.asList(new RecordField("person", RecordFieldType.RECORD.getRecordDataType(person)), new RecordField("json_str", RecordFieldType.STRING.getDataType())));
    // test CHOICE resulting in nested ARRAY of Records
    final Record mapAddressesArray = new MapRecord(schema, Collections.singletonMap("json_str", "{\"firstName\":\"John\",\"age\":30,\"nicknames\":[\"J\",\"Johnny\"],\"addresses\":[{\"address_1\":\"123 Somewhere Street\"},{\"address_1\":\"456 Anywhere Road\"}]}"));
    assertEquals(new HashMap<String, Object>() {

        {
            put("firstName", "John");
            put("age", 30);
            put("nicknames", Arrays.asList("J", "Johnny"));
            put("addresses", Arrays.asList(Collections.singletonMap("address_1", "123 Somewhere Street"), Collections.singletonMap("address_1", "456 Anywhere Road")));
        }
    }, RecordPath.compile("unescapeJson(/json_str)").evaluate(mapAddressesArray).getSelectedFields().findFirst().orElseThrow(IllegalStateException::new).getValue());
    // test CHOICE resulting in nested single RECORD
    final Record mapAddressesSingle = new MapRecord(schema, Collections.singletonMap("json_str", "{\"firstName\":\"John\",\"age\":30,\"nicknames\":[\"J\",\"Johnny\"],\"addresses\":{\"address_1\":\"123 Somewhere Street\"}}"));
    assertEquals(new HashMap<String, Object>() {

        {
            put("firstName", "John");
            put("age", 30);
            put("nicknames", Arrays.asList("J", "Johnny"));
            put("addresses", Collections.singletonMap("address_1", "123 Somewhere Street"));
        }
    }, RecordPath.compile("unescapeJson(/json_str, 'false')").evaluate(mapAddressesSingle).getSelectedFields().findFirst().orElseThrow(IllegalStateException::new).getValue());
    // test single Record converted from Map Object
    final Record recordFromMap = new MapRecord(schema, Collections.singletonMap("json_str", "{\"firstName\":\"John\",\"age\":30}"));
    assertEquals(DataTypeUtils.toRecord(new HashMap<String, Object>() {

        {
            put("firstName", "John");
            put("age", 30);
        }
    }, "json_str"), RecordPath.compile("unescapeJson(/json_str, 'true')").evaluate(recordFromMap).getSelectedFields().findFirst().orElseThrow(IllegalStateException::new).getValue());
    // test collection of Record converted from Map collection
    final Record recordCollectionFromMaps = new MapRecord(schema, Collections.singletonMap("json_str", "[{\"address_1\":\"123 Somewhere Street\"},{\"address_1\":\"456 Anywhere Road\"}]"));
    assertEquals(Arrays.asList(DataTypeUtils.toRecord(Collections.singletonMap("address_1", "123 Somewhere Street"), "json_str"), DataTypeUtils.toRecord(Collections.singletonMap("address_1", "456 Anywhere Road"), "json_str")), RecordPath.compile("unescapeJson(/json_str, 'true')").evaluate(recordCollectionFromMaps).getSelectedFields().findFirst().orElseThrow(IllegalStateException::new).getValue());
    // test simple String field
    final Record recordJustName = new MapRecord(schema, Collections.singletonMap("json_str", "{\"firstName\":\"John\"}"));
    assertEquals(new HashMap<String, Object>() {

        {
            put("firstName", "John");
        }
    }, RecordPath.compile("unescapeJson(/json_str)").evaluate(recordJustName).getSelectedFields().findFirst().orElseThrow(IllegalStateException::new).getValue());
    // test simple String
    final Record recordJustString = new MapRecord(schema, Collections.singletonMap("json_str", "\"John\""));
    assertEquals("John", RecordPath.compile("unescapeJson(/json_str)").evaluate(recordJustString).getSelectedFields().findFirst().orElseThrow(IllegalStateException::new).getValue());
    // test simple Int
    final Record recordJustInt = new MapRecord(schema, Collections.singletonMap("json_str", "30"));
    assertEquals(30, RecordPath.compile("unescapeJson(/json_str)").evaluate(recordJustInt).getSelectedFields().findFirst().orElseThrow(IllegalStateException::new).getValue());
    // test invalid JSON
    final Record recordInvalidJson = new MapRecord(schema, Collections.singletonMap("json_str", "{\"invalid\": \"json"));
    RecordPathException rpe = assertThrows(RecordPathException.class, () -> RecordPath.compile("unescapeJson(/json_str)").evaluate(recordInvalidJson).getSelectedFields().findFirst().orElseThrow(IllegalStateException::new).getValue());
    assertEquals("Unable to deserialise JSON String into Record Path value", rpe.getMessage());
    // test not String
    final Record recordNotString = new MapRecord(schema, Collections.singletonMap("person", new MapRecord(person, Collections.singletonMap("age", 30))));
    IllegalArgumentException iae = assertThrows(IllegalArgumentException.class, () -> RecordPath.compile("unescapeJson(/person/age)").evaluate(recordNotString).getSelectedFields().findFirst().orElseThrow(IllegalStateException::new).getValue());
    assertEquals("Argument supplied to unescapeJson must be a String", iae.getMessage());
}

