public void testReadExactlyOnceFields() throws IOException {
    final List<RecordField> fields = new ArrayList<>();
    fields.add(new SimpleRecordField("int", FieldType.INT, Repetition.EXACTLY_ONE));
    fields.add(new SimpleRecordField("boolean", FieldType.BOOLEAN, Repetition.EXACTLY_ONE));
    fields.add(new SimpleRecordField("byte array", FieldType.BYTE_ARRAY, Repetition.EXACTLY_ONE));
    fields.add(new SimpleRecordField("long", FieldType.LONG, Repetition.EXACTLY_ONE));
    fields.add(new SimpleRecordField("string", FieldType.STRING, Repetition.EXACTLY_ONE));
    fields.add(new SimpleRecordField("long string", FieldType.LONG_STRING, Repetition.EXACTLY_ONE));
    fields.add(new ComplexRecordField("complex", Repetition.EXACTLY_ONE, new SimpleRecordField("key", FieldType.STRING, Repetition.EXACTLY_ONE), new SimpleRecordField("value", FieldType.STRING, Repetition.EXACTLY_ONE)));
    fields.add(new MapRecordField("map", new SimpleRecordField("key", FieldType.STRING, Repetition.EXACTLY_ONE), new SimpleRecordField("value", FieldType.STRING, Repetition.ZERO_OR_ONE), Repetition.EXACTLY_ONE));
    fields.add(new UnionRecordField("union1", Repetition.EXACTLY_ONE, Arrays.asList(new RecordField[] { new SimpleRecordField("one", FieldType.STRING, Repetition.EXACTLY_ONE), new SimpleRecordField("two", FieldType.INT, Repetition.EXACTLY_ONE) })));
    fields.add(new UnionRecordField("union2", Repetition.EXACTLY_ONE, Arrays.asList(new RecordField[] { new SimpleRecordField("one", FieldType.STRING, Repetition.EXACTLY_ONE), new SimpleRecordField("two", FieldType.INT, Repetition.EXACTLY_ONE) })));
    final RecordSchema schema = new RecordSchema(fields);
    final SchemaRecordReader reader = SchemaRecordReader.fromSchema(schema, new NoOpFieldCache());
    final byte[] buffer;
    try (final ByteArrayOutputStream baos = new ByteArrayOutputStream();
        final DataOutputStream dos = new DataOutputStream(baos)) {
        // sentinel byte
        dos.write(1);
        dos.writeInt(42);
        dos.writeBoolean(true);
        final byte[] array = "hello".getBytes();
        dos.writeInt(array.length);
        dos.write(array);
        dos.writeLong(42L);
        dos.writeUTF("hello");
        final String longString = "hello";
        final byte[] longStringArray = longString.getBytes(StandardCharsets.UTF_8);
        dos.writeInt(longStringArray.length);
        dos.write(longStringArray);
        dos.writeUTF("key");
        dos.writeUTF("value");
        dos.writeInt(2);
        dos.writeUTF("key1");
        dos.writeBoolean(true);
        dos.writeUTF("value1");
        dos.writeUTF("key2");
        dos.writeBoolean(false);
        dos.writeUTF("one");
        dos.writeUTF("hello");
        dos.writeUTF("two");
        dos.writeInt(42);
        buffer = baos.toByteArray();
    }
    try (final ByteArrayInputStream in = new ByteArrayInputStream(buffer)) {
