    final List<HashAlgorithm> algorithms = List.of(HashAlgorithm.values());
    // Act
    final List<String> descriptions = algorithms.stream().map(algorithm -> algorithm.buildAllowableValueDescription()).collect(Collectors.toList());
    // Assert
    descriptions.forEach(description -> {
        final Pattern pattern = Pattern.compile(".* \\(\\d+ byte output\\).*");
        final Matcher matcher = pattern.matcher(description);
        assertTrue(matcher.find());
    });
    descriptions.stream().filter(description -> {
        final Pattern pattern = Pattern.compile("MD2|MD5|SHA-1");
        final Matcher matcher = pattern.matcher(description);
        return matcher.find();
    }).forEach(description -> assertTrue(description.contains("WARNING")));
}

