@Test
public void testAddAndCompare() {
    final byte[] pattern = new byte[] { '\r', '0', 38, 48 };
    final byte[] search = new byte[] { '\r', '0', 38, 58, 58, 83, 78, '\r', '0', 38, 48, 83, 92, 78, 4, 38 };
    final NaiveSearchRingBuffer circ = new NaiveSearchRingBuffer(pattern);
    int counter = -1;
    for (final byte b : search) {
        counter++;
        final boolean matched = circ.addAndCompare(b);
        if (counter == 10) {
            assertTrue(matched);
        } else {
            assertFalse(matched);
        }
    }
}

