public void testProcessPoisonPillRecordWithCheckpoint() throws ShutdownException, InvalidStateException {
    final ProcessRecordsInput processRecordsInput = ProcessRecordsInput.builder().records(Arrays.asList(KinesisClientRecord.builder().approximateArrivalTimestamp(null).partitionKey("partition-1").sequenceNumber("1").data(ByteBuffer.wrap("record-1".getBytes(StandardCharsets.UTF_8))).build(), kinesisRecord, KinesisClientRecord.builder().approximateArrivalTimestamp(null).partitionKey("partition-3").sequenceNumber("3").data(ByteBuffer.wrap("record-3".getBytes(StandardCharsets.UTF_8))).build())).checkpointer(checkpointer).cacheEntryTime(Instant.now().minus(1, ChronoUnit.MINUTES)).cacheExitTime(Instant.now().minus(1, ChronoUnit.SECONDS)).millisBehindLatest(100L).build();
