@Test
public void testInvalidDynamicKCLProperties() {
    // blank properties
    runner.setProperty("", "empty");
    runner.setProperty(" ", "blank");
    // invalid property names
    runner.setProperty("withPrefixNotAllowed", "a-value");
    runner.setProperty("unknownProperty", "a-third-value");
    runner.setProperty("toString", "cannot-call");
    // invalid property names (cannot use nested/indexed/mapped properties via BeanUtils)
    runner.setProperty("no.allowed", "no-.");
    runner.setProperty("no[allowed", "no-[");
    runner.setProperty("no]allowed", "no-]");
    runner.setProperty("no(allowed", "no-(");
    runner.setProperty("no)allowed", "no-)");
    // can't override static properties
    runner.setProperty("leaseManagementConfig.failoverTimeMillis", "1000");
    runner.setProperty("leaseManagementConfig.initialPositionInStream", "AT_TIMESTAMP");
    // invalid parameter conversions
    runner.setProperty("checkpointConfig.checkpointFactory", "too-complex");
    runner.setProperty("coordinatorConfig.schedulerInitializationBackoffTimeMillis", "not-long");
    // valid dynamic parameters
    runner.setProperty("namespace", "value");
    final AssertionError ae = assertThrows(AssertionError.class, runner::assertValid);
    assertThat(ae.getMessage(), startsWith("Processor has 13 validation failures:\n"));
    // blank properties
    assertThat(ae.getMessage(), containsString("'Property Name' validated against '' is invalid because Invalid attribute key: <Empty String>\n"));
    assertThat(ae.getMessage(), containsString("'Property Name' validated against ' ' is invalid because Invalid attribute key: <Empty String>\n"));
    // invalid property names
    assertThat(ae.getMessage(), containsString("'withPrefixNotAllowed' validated against 'a-value' is invalid because Property name must not have a prefix of \"with\", " + "must start with a letter and contain only letters, numbers, periods, or underscores\n"));
    assertThat(ae.getMessage(), containsString("'unknownProperty' validated against 'a-third-value' is invalid because Kinesis Client Configuration Builder property with name " + "UnknownProperty does not exist or is not writable\n"));
    assertThat(ae.getMessage(), containsString("'toString' validated against 'cannot-call' is invalid because Kinesis Client Configuration Builder property with name " + "ToString does not exist or is not writable\n"));
    // invalid property names (cannot use nested/indexed/mapped properties via BeanUtils)
    assertThat(ae.getMessage(), containsString("'no[allowed' validated against 'no-[' is invalid because Property name must not have a prefix of \"with\", " + "must start with a letter and contain only letters, numbers, periods, or underscores\n"));
    assertThat(ae.getMessage(), containsString("'no]allowed' validated against 'no-]' is invalid because Property name must not have a prefix of \"with\", " + "must start with a letter and contain only letters, numbers, periods, or underscores\n"));
    assertThat(ae.getMessage(), containsString("'no(allowed' validated against 'no-(' is invalid because Property name must not have a prefix of \"with\", " + "must start with a letter and contain only letters, numbers, periods, or underscores\n"));
    assertThat(ae.getMessage(), containsString("'no)allowed' validated against 'no-)' is invalid because Property name must not have a prefix of \"with\", " + "must start with a letter and contain only letters, numbers, periods, or underscores\n"));
    // can't override static properties
    assertThat(ae.getMessage(), containsString("'leaseManagementConfig.failoverTimeMillis' validated against '1000' is invalid because Use \"Failover Timeout\" instead of a dynamic property\n"));
    assertThat(ae.getMessage(), containsString("'leaseManagementConfig.initialPositionInStream' validated against 'AT_TIMESTAMP' is invalid because Use \"Initial Stream Position\" instead of a dynamic property\n"));
    // invalid parameter conversions
    assertThat(ae.getMessage(), containsString("'checkpointConfig.checkpointFactory' validated against 'too-complex' is invalid because Kinesis Client Configuration Builder property " + "with name CheckpointConfig.checkpointFactory cannot be used with value \"too-complex\" : " + "Cannot invoke software.amazon.kinesis.checkpoint.CheckpointConfig.checkpointFactory on bean class " + "'class software.amazon.kinesis.checkpoint.CheckpointConfig' - argument type mismatch - had objects of type \"java.lang.String\" " + "but expected signature \"software.amazon.kinesis.checkpoint.CheckpointFactory\"\n"));
}

