@Test
public void testSimpleDelete() {
    final SendMessageRequest request = SendMessageRequest.builder().queueUrl(getQueueUrl()).messageBody("Hello World").build();
    final SendMessageResponse response = getClient().sendMessage(request);
    assertTrue(response.sdkHttpResponse().isSuccessful());
    // Setup - receive message to get receipt handle
    final ReceiveMessageRequest receiveMessageRequest = ReceiveMessageRequest.builder().queueUrl(getQueueUrl()).build();
    final ReceiveMessageResponse receiveMessageResult = getClient().receiveMessage(receiveMessageRequest);
    assertEquals(200, receiveMessageResult.sdkHttpResponse().statusCode());
    final Message deleteMessage = receiveMessageResult.messages().get(0);
    final String receiptHandle = deleteMessage.receiptHandle();
    // Test - delete message with DeleteSQS
    final TestRunner runner = initRunner(DeleteSQS.class);
    final Map<String, String> ffAttributes = new HashMap<>();
    ffAttributes.put("filename", "1.txt");
    ffAttributes.put("sqs.receipt.handle", receiptHandle);
    runner.enqueue("TestMessageBody", ffAttributes);
    runner.run(1);
    runner.assertAllFlowFilesTransferred(DeleteSQS.REL_SUCCESS, 1);
}

@Test
public void testSimpleGet() {
    final int messageCount = 4;
    for (int i = 0; i < messageCount; i++) {
        final SendMessageRequest request = SendMessageRequest.builder().queueUrl(getQueueUrl()).messageBody("Hello World " + i).messageAttributes(Map.of("i", MessageAttributeValue.builder().stringValue(Integer.toString(i)).dataType("String").build())).build();
        final SendMessageResponse response = getClient().sendMessage(request);
        assertTrue(response.sdkHttpResponse().isSuccessful());
    }
    final TestRunner runner = initRunner(GetSQS.class);
    runner.setProperty(GetSQS.TIMEOUT, "30 secs");
    runner.run();
    int count = runner.getFlowFilesForRelationship(GetSQS.REL_SUCCESS).size();
    while (count < messageCount) {
        runner.run(1, false, false);
        count = runner.getFlowFilesForRelationship(GetSQS.REL_SUCCESS).size();
    }
    runner.run();
    runner.assertAllFlowFilesTransferred(GetSQS.REL_SUCCESS, messageCount);
    final List<MockFlowFile> flowFiles = runner.getFlowFilesForRelationship(GetSQS.REL_SUCCESS);
    for (int i = 0; i < messageCount; i++) {
        final String attributeValue = Integer.toString(i);
        final String messageBody = "Hello World " + i;
        final long matchingCount = flowFiles.stream().filter(ff -> attributeValue.equals(ff.getAttribute("sqs.i"))).filter(ff -> messageBody.equals(ff.getContent())).count();
        assertEquals(1L, matchingCount);
    }
}

