@Test
void testFileUploadLargeFile() throws Exception {
    MockFlowFile mockFlowFile = getMockFlowFile(LARGE_CONTENT_30B);
    testRunner.setProperty(PutDropbox.FILE_NAME, FILENAME_1);
    testRunner.setProperty(PutDropbox.CHUNKED_UPLOAD_SIZE, CHUNKED_UPLOAD_SIZE_IN_BYTES + " B");
    testRunner.setProperty(PutDropbox.CHUNKED_UPLOAD_THRESHOLD, CHUNKED_UPLOAD_THRESHOLD_IN_BYTES + " B");
    when(mockDropboxClient.files()).thenReturn(mockDbxUserFilesRequest);
    //start session: 8 bytes uploaded
    when(mockDbxUserFilesRequest.uploadSessionStart()).thenReturn(mockUploadSessionStartUploader);
    when(mockUploadSessionStartUploader.uploadAndFinish(any(InputStream.class), eq(CHUNKED_UPLOAD_SIZE_IN_BYTES))).thenReturn(mockUploadSessionStartResult);
    when(mockUploadSessionStartResult.getSessionId()).thenReturn(SESSION_ID);
    //append session: invoked twice, 2 * 8 bytes uploaded
    when(mockDbxUserFilesRequest.uploadSessionAppendV2(any(UploadSessionCursor.class))).thenReturn(mockUploadSessionAppendV2Uploader);
    //finish session: 30 - 8 - 2 * 8 = 6 bytes uploaded
    when(mockDbxUserFilesRequest.uploadSessionFinish(any(UploadSessionCursor.class), any(CommitInfo.class))).thenReturn(mockUploadSessionFinishUploader);
    when(mockUploadSessionFinishUploader.uploadAndFinish(any(InputStream.class), anyLong())).thenReturn(createFileMetadata(FILE_ID_1, FILENAME_1, TEST_FOLDER, CREATED_TIME));
    testRunner.enqueue(mockFlowFile);
    testRunner.run();
    testRunner.assertAllFlowFilesTransferred(PutDropbox.REL_SUCCESS, 1);
    verify(mockUploadSessionAppendV2Uploader, times(2)).uploadAndFinish(any(InputStream.class), eq(CHUNKED_UPLOAD_SIZE_IN_BYTES));
    assertProvenanceEvent(ProvenanceEventType.SEND);
}

