    final List<IndexOperationRequest> ops = Arrays.asList(new IndexOperationRequest(INDEX, type, "1", new MapBuilder().of("msg", "one", "intField", 1).build(), IndexOperationRequest.Operation.Index, null, false, null, // OK
    null), new IndexOperationRequest(INDEX, type, "2", new MapBuilder().of("msg", "two", "intField", 1).build(), IndexOperationRequest.Operation.Create, null, false, null, // already exists
    null), new IndexOperationRequest(INDEX, type, "1", new MapBuilder().of("msg", "one", "intField", "notaninteger").build(), IndexOperationRequest.Operation.Index, null, false, null, // can't parse int field
    null));
    final IndexOperationResponse response = service.bulk(ops, createParameters("refresh", "true"));
    assertTrue(response.hasErrors());
    assertEquals(2, response.getItems().stream().filter(it -> {
        final Optional<String> first = it.keySet().stream().findFirst();
        if (first.isPresent()) {
            final String key = first.get();
            return ((Map<String, Object>) it.get(key)).containsKey("error");
        } else {
            throw new IllegalStateException("Cannot find index response operation items");
        }
    }).count());
}

