    });
    assertSendEvent(runner, input);
    reset(runner);
    // paged query hits combined
    runner.setProperty(AbstractJsonQueryElasticsearch.SEARCH_RESULTS_SPLIT, ResultOutputStrategy.PER_QUERY.getValue());
