        final String rangeValue = JsonPath.read(query, String.format("$.query.bool.filter[0].range.%s.gt", RANGE_FIELD_NAME));
        assertEquals(StringUtils.isNotBlank(stateValue) ? stateValue : initialValue, rangeValue);
    }
