    assertNotNull(finishedFound.getAttribute("ip.geo.lookup.micros"));
    assertEquals("Minneapolis", finishedFound.getAttribute("ip.geo.city"));
    assertEquals("44.98", finishedFound.getAttribute("ip.geo.latitude"));
