    }
}

@Test
public void testEncodeProtocolVersion1() throws IOException {
    final long id = 48;
    final int version = 2;
    final int protocolVersion = 1;
    final HortonworksEncodedSchemaReferenceWriter writer = new HortonworksEncodedSchemaReferenceWriter(protocolVersion);
    final RecordSchema schema = new SimpleRecordSchema(Collections.emptyList(), SchemaIdentifier.builder().name("name").id(id).version(version).build());
    final byte[] header;
    try (final ByteArrayOutputStream baos = new ByteArrayOutputStream()) {
        writer.writeHeader(schema, baos);
        header = baos.toByteArray();
    }
    try (final DataInputStream dis = new DataInputStream(new ByteArrayInputStream(header))) {
        // verify 'protocol version'
        assertEquals(protocolVersion, dis.read());
        // verify schema id
        assertEquals(id, dis.readLong());
        // verify schema version
        assertEquals(version, dis.readInt());
        // no more bytes
        assertEquals(-1, dis.read());
    }
}

