@Test()
public void testAuthorizedByComponentRead() {
    final MockPolicyBasedAuthorizer authorizer = new MockPolicyBasedAuthorizer();
    authorizer.addUser(AUTH_USER);
    authorizer.addAccessPolicy(new AccessPolicy.Builder().identifierGenerateRandom().addUser(AUTH_USER.getIdentifier()).resource("/processors/component-1").action(READ).build());
    PROCESSOR.authorize(authorizer, READ, USER);
    // If the user has only READ access to the base component WRITE and operation should be denied
    shouldBeDenied("Component WRITE should be denied", () -> PROCESSOR.authorize(authorizer, WRITE, USER));
    shouldBeDenied("Operation WRITE should be denied", () -> OperationAuthorizable.authorizeOperation(PROCESSOR, authorizer, USER));
}

@Test()
