        final DataFlow electedDataFlow = election.castVote(dataFlow, createNodeId(i));
        if (i == 7) {
            assertNotNull(electedDataFlow);
            assertEquals(new String(nonEmptyFlow), new String(electedDataFlow.getFlow()));
        } else {
            assertNull(electedDataFlow);
        }
    }
}

