    report = repo.reportTransferEvents(System.currentTimeMillis());
    entry = report.getReportEntry(id2);
    assertNull(entry);
    repo.close();
}

@Test
public void testAttributeCopiedOnModification() {
    final FlowFileRecord original = new StandardFlowFileRecord.Builder().addAttribute("uuid", UUID.randomUUID().toString()).addAttribute("abc", "xyz").build();
    final FlowFileRecord addAttribute = new StandardFlowFileRecord.Builder().fromFlowFile(original).addAttribute("hello", "good-bye").build();
