    when(mockDriverService.files().list().setSupportsAllDrives(true).setIncludeItemsFromAllDrives(true).setQ("('null' in parents) and (mimeType != 'application/vnd.google-apps.folder') and (mimeType != 'application/vnd.google-apps.shortcut') and trashed = false").setPageToken(null).setFields("nextPageToken, files(id, name, size, createdTime, modifiedTime, mimeType)").execute().getFiles()).thenReturn(singletonList(createFile(id, filename, size, new DateTime(createdTime), new DateTime(modifiedTime), mimeType)));
    List<GoogleDriveFileInfo> expected = singletonList(new GoogleDriveFileInfo.Builder().id(id).fileName(filename).size(size).createdTime(createdTime).modifiedTime(modifiedTime).mimeType(mimeType).build());
    // WHEN
    List<GoogleDriveFileInfo> actual = testSubject.performListing(mockProcessContext, minTimestamp, null);
    // THEN
    List<Function<GoogleDriveFileInfo, Object>> propertyProviders = asList(GoogleDriveFileInfo::getId, GoogleDriveFileInfo::getIdentifier, GoogleDriveFileInfo::getName, GoogleDriveFileInfo::getSize, GoogleDriveFileInfo::getTimestamp, GoogleDriveFileInfo::getCreatedTime, GoogleDriveFileInfo::getModifiedTime, GoogleDriveFileInfo::getMimeType);
    List<EqualsWrapper<GoogleDriveFileInfo>> expectedWrapper = wrapList(expected, propertyProviders);
