    boolean userIsOwner = false;
    boolean projectOwnerIsReader = false;
    for (Acl acl : blob.listAcls()) {
        if (acl.getEntity().getType() == Acl.Entity.Type.USER && acl.getRole() == Acl.Role.OWNER) {
            userIsOwner = true;
        }
        if (acl.getEntity().getType() == Acl.Entity.Type.PROJECT && acl.getRole() == Acl.Role.READER) {
            projectOwnerIsReader = true;
        }
    }
    assertTrue(userIsOwner);
    assertTrue(projectOwnerIsReader);
}

