@Test
void testListingEmptyDir() {
    runner.setProperty(ListHDFS.DIRECTORY, "/test/emptyDir");
    addFileStatus("/test", "testFile.out", false);
    addFileStatus("/test", "testFile.txt", false);
    addFileStatus("/test", "emptyDir", true);
