@Test
public void testSimpleFields() throws SerDeException {
    NiFiRecordSerDe serDe = createSerDe("bytec,shortc,intc,longc,boolc,floatc,doublec,stringc,varcharc,charc,datec,timestampc,decimalc", "tinyint:smallint:int:bigint:boolean:float:double:string:varchar(50):char(1):date:timestamp:decimal");
    RecordSchema schema = new SimpleRecordSchema(Arrays.asList(new RecordField("bytec", RecordFieldType.BYTE.getDataType()), new RecordField("shortc", RecordFieldType.SHORT.getDataType()), new RecordField("intc", RecordFieldType.INT.getDataType()), new RecordField("longc", RecordFieldType.LONG.getDataType()), new RecordField("boolc", RecordFieldType.BOOLEAN.getDataType()), new RecordField("floatc", RecordFieldType.FLOAT.getDataType()), new RecordField("doublec", RecordFieldType.DOUBLE.getDataType()), new RecordField("stringc", RecordFieldType.STRING.getDataType()), new RecordField("varcharc", RecordFieldType.STRING.getDataType()), new RecordField("charc", RecordFieldType.CHAR.getDataType()), new RecordField("datec", RecordFieldType.DATE.getDataType("yyyy-MM-dd")), new RecordField("timestampc", RecordFieldType.TIMESTAMP.getDataType("yyyy-MM-dd HH:mm:ss")), new RecordField("decimalc", RecordFieldType.DOUBLE.getDataType())));
    long currentTimeMillis = System.currentTimeMillis();
    HashMap<String, Object> input = new HashMap<String, Object>() {

        {
            put("bytec", (byte) 2);
            put("shortc", (short) 45);
            put("intc", 95);
            put("longc", 876L);
            put("boolc", Boolean.TRUE);
            put("floatc", 4.56f);
            put("doublec", 2.3445);
            put("stringc", "test");
            put("varcharc", "test2");
            put("charc", 'c');
            put("datec", new java.sql.Date(currentTimeMillis));
            put("timestampc", new java.sql.Timestamp(currentTimeMillis));
            put("decimalc", 0.45);
        }
    };
    Date date = new Date();
    date.setTimeInMillis(currentTimeMillis);
    Timestamp ts = new Timestamp();
    ts.setTimeInMillis(currentTimeMillis);
    List<Object> expected = Arrays.asList(Byte.valueOf("2"), Short.valueOf("45"), 95, 876L, Boolean.TRUE, 4.56f, 2.3445, "test", "test2", "c", date, ts, HiveDecimal.create("0.45"));
    Object deserialized = serDe.deserialize(new ObjectWritable(new MapRecord(schema, input)));
    assertEquals(expected, deserialized);
}

