    schema = new Schema.Parser().parse(avroSchema);
    processor.setFields(Arrays.asList(new FieldSchema("uuid", serdeConstants.STRING_TYPE_NAME, "uuid"), new FieldSchema("stringc", serdeConstants.STRING_TYPE_NAME, "stringc"), new FieldSchema("charc", serdeConstants.CHAR_TYPE_NAME + "(1)", "charc"), new FieldSchema("varcharc", serdeConstants.VARCHAR_TYPE_NAME + "(100)", "varcharc"), new FieldSchema("intc", serdeConstants.INT_TYPE_NAME, "intc"), new FieldSchema("tinyintc", serdeConstants.TINYINT_TYPE_NAME, "tinyintc"), new FieldSchema("smallintc", serdeConstants.SMALLINT_TYPE_NAME, "smallintc"), new FieldSchema("bigintc", serdeConstants.BIGINT_TYPE_NAME, "bigintc"), new FieldSchema("booleanc", serdeConstants.BOOLEAN_TYPE_NAME, "booleanc"), new FieldSchema("floatc", serdeConstants.FLOAT_TYPE_NAME, "floatc"), new FieldSchema("doublec", serdeConstants.DOUBLE_TYPE_NAME, "doublec"), new FieldSchema("bytesc", serdeConstants.BINARY_TYPE_NAME, "bytesc"), new FieldSchema("listc", serdeConstants.LIST_TYPE_NAME + "<" + serdeConstants.STRING_TYPE_NAME + ">", "listc"), new FieldSchema("structc", serdeConstants.STRUCT_TYPE_NAME + "<sint:" + serdeConstants.INT_TYPE_NAME + "," + "sboolean:" + serdeConstants.BOOLEAN_TYPE_NAME + "," + "sstring:" + serdeConstants.STRING_TYPE_NAME + ">", "structc"), new FieldSchema("mapc", serdeConstants.MAP_TYPE_NAME + "<" + serdeConstants.STRING_TYPE_NAME + "," + serdeConstants.INT_TYPE_NAME + ">", "mapc"), new FieldSchema("datec", serdeConstants.DATE_TYPE_NAME, "datec"), new FieldSchema("timestampc", serdeConstants.TIMESTAMP_TYPE_NAME, "timestampc"), new FieldSchema("decimalc", serdeConstants.DECIMAL_TYPE_NAME + "(4,2)", "decimalc"), new FieldSchema("enumc", serdeConstants.STRING_TYPE_NAME, "enumc")));
    runner = TestRunners.newTestRunner(processor);
    runner.setProperty(PutHive3Streaming.HIVE_CONFIGURATION_RESOURCES, TEST_CONF_PATH);
    MockRecordParser readerFactory = new MockRecordParser();
    final RecordSchema recordSchema = AvroTypeUtil.createSchema(schema);
    for (final RecordField recordField : recordSchema.getFields()) {
        //add the schema field so that we don't loose the map value data type for
        //mapc field and element type for listc field
        readerFactory.addSchemaField(recordField);
    }
    List<String> enumc = Arrays.asList("SPADES", "HEARTS", "DIAMONDS", "CLUBS");
    Random r = new Random();
    for (int index = 0; index < 10; index++) {
        final int i = index;
        Record structRecord = new // Get non-null type in union
        MapRecord(// Get non-null type in union
        AvroTypeUtil.createSchema(schema.getField("structc").schema().getTypes().get(1)), new HashMap<String, Object>() {

            {
                // {"name": "sint", "type": "int"},
                put("sint", i + 2);
                if (i % 3 == 2) {
                    put("sboolean", null);
                } else {
                    // {"name": "sboolean", "type": ["null","boolean"]},
                    put("sboolean", i % 3 == 1);
                }
                // {"name": "sstring", "type": "string"}
                put("sstring", "world");
            }
        });
        readerFactory.addRecord(// {"name": "uuid", "type": "string"},
        UUID.randomUUID(), // {"name": "stringc", "type": "string"},
        "hello", 'a', "world", // {"name": "intc", "type": "int"},
        i, // {"name": "tinyintc", "type": ["null", "int"]},
        i + 1, // {"name": "smallintc", "type": "int"},
        i * 10, // {"name": "bigintc", "type": "long"},
        i * Integer.MAX_VALUE, // {"name": "booleanc", "type": "boolean"},
        i % 2 == 0, // {"name": "floatc", "type": "floatc"},
        i * 100.0f, // {"name": "doublec", "type": "double"},
        i * 100.0, "Hello".getBytes(), // {"name": "listc", "type": ["null", {"type": "array", "items": "string"}]},
        new String[] { "a", "b" }, structRecord, new //"name": "mapType", "type": "map", "values": "string"}
        HashMap<String, Integer>() {

            {
                // {"name": "sint", "type": "int"},
                put("sint1", i + 2);
                // {"name": "x", "type": "int"},
                put("sint2", i);
            }
        }, new java.sql.Date(Calendar.getInstance().getTimeInMillis()), Timestamp.from(Instant.now()), i * 99.0 / 100, // {"name": "enumc", "type": {"type": "enum", "name": "Suit", "symbols": ["SPADES","HEARTS","DIAMONDS","CLUBS"]}}
        enumc.get(r.nextInt(4)));
    }
    runner.addControllerService("mock-reader-factory", readerFactory);
    runner.enableControllerService(readerFactory);
    runner.setProperty(PutHive3Streaming.RECORD_READER, "mock-reader-factory");
    runner.setProperty(PutHive3Streaming.METASTORE_URI, "thrift://localhost:9083");
    runner.setProperty(PutHive3Streaming.DB_NAME, "default");
    runner.setProperty(PutHive3Streaming.TABLE_NAME, "users");
    runner.enqueue(new byte[0]);
    runner.run();
    runner.assertTransferCount(PutHive3Streaming.REL_SUCCESS, 1);
    final MockFlowFile flowFile = runner.getFlowFilesForRelationship(PutHive3Streaming.REL_SUCCESS).get(0);
    assertEquals("10", flowFile.getAttribute(HIVE_STREAMING_RECORD_COUNT_ATTR));
    assertEquals("default.users", flowFile.getAttribute(ATTR_OUTPUT_TABLES));
}

