@Test
public void testValidateSchemaAttribute() {
    // normal schema
    String schemaAttribute = "{
" + "	"fields": [{
" + "		"tsName": "s1",
" + "		"dataType": "INT32",
" + "		"encoding": "RLE"
" + "	}, {
" + "		"tsName": "s2",
" + "		"dataType": "DOUBLE",
" + "		"encoding": "PLAIN"
" + "	}]
" + "}";
    ValidationResult result = processor.validateSchemaAttribute(schemaAttribute);
    assertTrue(result.isValid());
    assertNull(result.getMessage());
    // schema with wrong field
    schemaAttribute = "{
" + "	"field": [{
" + "		"tsName": "s1",
" + "		"dataType": "INT32",
" + "		"encoding": "RLE"
" + "	}, {
" + "		"tsName": "s2",
" + "		"dataType": "DOUBLE",
" + "		"encoding": "PLAIN"
" + "	}]
" + "}";
    result = processor.validateSchemaAttribute(schemaAttribute);
    String exceptedMsg = "The JSON of schema must contain `fields`";
    assertFalse(result.isValid());
    assertEquals(exceptedMsg, result.getMessage());
    // schema without tsName
    schemaAttribute = "{
" + "	"fields": [{
" + "		"dataType": "INT32",
" + "		"encoding": "RLE"
" + "	}, {
" + "		"tsName": "s2",
" + "		"dataType": "DOUBLE",
" + "		"encoding": "PLAIN"
" + "	}]
" + "}";
    result = processor.validateSchemaAttribute(schemaAttribute);
    exceptedMsg = "`tsName` or `dataType` has not been set";
    assertFalse(result.isValid());
    assertEquals(exceptedMsg, result.getMessage());
    // schema without data type
    schemaAttribute = "{
" + "	"fields": [{
" + "		"tsName": "s1",
" + "		"encoding": "RLE"
" + "	}, {
" + "		"tsName": "s2",
" + "		"dataType": "DOUBLE",
" + "		"encoding": "PLAIN"
" + "	}]
" + "}";
    result = processor.validateSchemaAttribute(schemaAttribute);
    exceptedMsg = "`tsName` or `dataType` has not been set";
    assertFalse(result.isValid());
    assertEquals(exceptedMsg, result.getMessage());
    // schema with wrong data type
    schemaAttribute = "{
" + "	"fields": [{
" + "		"tsName": "s1",
" + "		"dataType": "INT",
" + "		"encoding": "RLE"
" + "	}, {
" + "		"tsName": "s2",
" + "		"dataType": "DOUBLE",
" + "		"encoding": "PLAIN"
" + "	}]
" + "}";
    result = processor.validateSchemaAttribute(schemaAttribute);
    exceptedMsg = "Unknown `dataType`: INT. The supported dataTypes are [FLOAT, INT64, INT32, TEXT, DOUBLE, BOOLEAN]";
    assertFalse(result.isValid());
    assertEquals(exceptedMsg, result.getMessage());
    // schema with wrong key
    schemaAttribute = "{
" + "	"fields": [{
" + "		"tsName": "s1",
" + "		"dataType": "INT32",
" + "		"encode": "RLE"
" + "	}, {
" + "		"tsName": "s2",
" + "		"dataType": "DOUBLE",
" + "		"encoding": "PLAIN"
" + "	}]
" + "}";
    result = processor.validateSchemaAttribute(schemaAttribute);
    exceptedMsg = "Unknown property or properties: [encode]";
    assertFalse(result.isValid());
    assertEquals(exceptedMsg, result.getMessage());
    // schema with wrong compression type
    schemaAttribute = "{
" + "	"fields": [{
" + "		"tsName": "s1",
" + "		"dataType": "INT32",
" + "		"encoding": "RLE",
" + "		"compressionType": "ZIP"
" + "	}, {
" + "		"tsName": "s2",
" + "		"dataType": "DOUBLE",
" + "		"encoding": "PLAIN",
" + "		"compressionType": "GZIP"
" + "	}]
" + "}";
    result = processor.validateSchemaAttribute(schemaAttribute);
    exceptedMsg = "Unknown `compressionType`: ZIP, The supported compressionType are [UNCOMPRESSED, LZ4, GZIP, SNAPPY]";
    assertFalse(result.isValid());
    assertEquals(exceptedMsg, result.getMessage());
}

