@Test
public void testSearchForInverseValue() throws InterruptedException {
    repo = new VolatileProvenanceRepository(NiFiProperties.createBasicNiFiProperties(null));
    final Map<String, String> attributes = new HashMap<>();
    attributes.put("abc", "xyz");
    final ProvenanceEventBuilder builder = new StandardProvenanceEventRecord.Builder();
    builder.setEventTime(System.currentTimeMillis());
    builder.setEventType(ProvenanceEventType.RECEIVE);
    builder.setTransitUri("nifi://unit-test");
    builder.setComponentId("1234");
    builder.setComponentType("dummy processor");
    final String uuid_prefix = "00000000-0000-0000-0000-000000000000";
    for (int i = 0; i < 2; i++) {
        attributes.put("uuid", uuid_prefix + i);
        attributes.put("file.owner", "testOwner1");
        builder.fromFlowFile(createFlowFile(i, 3000L, attributes));
        repo.registerEvent(builder.build());
    }
    for (int i = 2; i < 10; i++) {
        attributes.put("uuid", uuid_prefix + i);
        attributes.put("file.owner", "testOwner2");
        builder.fromFlowFile(createFlowFile(i, 3000L, attributes));
        repo.registerEvent(builder.build());
    }
    final Query query = new Query(UUID.randomUUID().toString());
    query.addSearchTerm(SearchTerms.newSearchTerm(SearchableFields.ComponentID, "1234", null));
    query.addSearchTerm(SearchTerms.newSearchTerm(SearchableFields.newSearchableAttribute("abc"), "x?z", null));
    // set up query to search for event with uuid NOT ending in *000 and file.owner NOT testOwner2 and testAttribute NOT fitting pattern of testAttributeValu?
    query.addSearchTerm(SearchTerms.newSearchTerm(SearchableFields.FlowFileUUID, "*000", Boolean.TRUE));
    query.addSearchTerm(SearchTerms.newSearchTerm(SearchableFields.newSearchableAttribute("file.owner"), "testOwner2", Boolean.TRUE));
    query.addSearchTerm(SearchTerms.newSearchTerm(SearchableFields.newSearchableAttribute("testAttribute"), "testAttributeValu?", Boolean.TRUE));
    query.setMaxResults(100);
    final QuerySubmission submission = repo.submitQuery(query, createUser());
    while (!submission.getResult().isFinished()) {
        Thread.sleep(100L);
    }
    assertEquals(1, submission.getResult().getMatchingEvents().size());
    assertEquals("00000000-0000-0000-0000-0000000000001", submission.getResult().getMatchingEvents().get(0).getFlowFileUuid());
}

@Test
public void testObjectsBound() {
    final JavaObjectBindings bindings = new JavaObjectBindings();
    final String objectId = "oTestObject1";
    final String methodName = "testMethod";
    final CommandBuilder builder = new CommandBuilder(bindings, objectId, methodName);
    final Iterable<Object> iterable = new Iterable<>() {

        @Override
        public Iterator<Object> iterator() {
            return null;
        }
    };
    final Object[] args = new Object[] { "string", 1, 1.0F, 1.0D, 1L, null, true, 'c', (byte) 1, (short) 1, "hello world".getBytes(), new Object(), new int[2], new Object[2], new ArrayList<>(), new HashSet<>(), iterable };
    final String command = builder.buildCommand(args);
    // Ensure that we bind an ID for each object (except for String and byte[]) and not the primitives.
    // So we should have a bound ID for each of the following:
    // new Object()
    // new int[2]
    // new Object[2]
    // new ArrayList<>()
    // new HashSet<>()
    // iterable
    assertEquals(6, builder.getBoundIds().size());
    // Ensure that the command has the appropriate header
    final String[] commandSplits = command.split("\n");
    assertEquals(CommandBuilder.METHOD_INVOCATION_START_CLAUSE.trim(), commandSplits[0]);
    assertEquals(objectId, commandSplits[1]);
    assertEquals(methodName, commandSplits[2]);
    // Verify the primitive arguments
    assertTrue(commandSplits[3].contains("string"));
    assertTrue(commandSplits[4].contains("1"));
    assertTrue(commandSplits[5].contains("1.0"));
    assertTrue(commandSplits[6].contains("1.0"));
    assertTrue(commandSplits[7].contains("1"));
    // n is used for null values
    assertEquals("n", commandSplits[8]);
    assertTrue(commandSplits[9].contains("true"));
    assertTrue(commandSplits[10].contains("c"));
    assertTrue(commandSplits[11].contains("1"));
    assertTrue(commandSplits[12].contains("1"));
    final List<String> boundIds = builder.getBoundIds();
    // Verify the object arguments
    for (int splitIndex = 14; splitIndex < commandSplits.length - 1; splitIndex++) {
        final String argId = commandSplits[splitIndex].substring(1);
        assertTrue(boundIds.contains(argId));
        assertSame(args[splitIndex - 3], bindings.getBoundObject(argId));
    }
    // Ensure that the command ends with the appropriate footer
    assertEquals(CommandBuilder.METHOD_INVOCATION_END_CLAUSE.trim(), commandSplits[commandSplits.length - 1]);
}

