        assertEquals(attributes.get(QuerySolr.ATTRIBUTE_SOLR_START), Integer.toString(startParam));
        startParam += 2;
        StringBuilder expectedXml = new StringBuilder().append("<docs><doc><field name=\"id\">doc").append(documentCounter++).append("</field></doc><doc><field name=\"id\">doc").append(documentCounter++).append("</field></doc></docs>");
        assertThat(expectedXml.toString(), CompareMatcher.isIdenticalTo(new String(runner.getContentAsByteArray(flowFile))));
    }
}

