" + "        "second": {
" + "            "third": [
" + "                "one",
" + "                "two",
" + "                "three",
" + "                "four",
" + "                "five"
" + "            ]
" + "        }
" + "    }
" + "}";
    final Map parsed = (Map) baseTest(testRunner, json, 2);
    assertEquals(parsed.get("test.msg"), "Hello, world", "test.msg should exist, but doesn't");
