    splits.get(1).assertAttributeEquals(SplitText.FRAGMENT_SIZE, "54");
    final String fragmentUUID = splits.get(0).getAttribute(SplitText.FRAGMENT_ID);
    for (int i = 0; i < splits.size(); i++) {
