    final List<MockFlowFile> packed = mergeRunner.getFlowFilesForRelationship(MergeContent.REL_MERGED);
    for (final MockFlowFile flowFile : packed) {
        flowFile.assertAttributeEquals(CoreAttributes.FILENAME.key(), "data.tar");
    }
