    assertArrayEquals(new Object[] { "44 Shirley Ave.", "Los Angeles" }, ((Record) valuesThirdRecord[valuesThirdRecord.length - 1]).getValues());
    Object[] valuesFourthRecord = reader.nextRecord().getValues();
