@Test
void testChoseSuboptimalSchemaWhenDataHasExtraFields() throws Exception {
    String yamlPath = "src/test/resources/yaml/choice-of-different-arrays-with-extra-fields.yaml";
    SimpleRecordSchema recordSchema1 = new SimpleRecordSchema(Arrays.asList(new RecordField("integer", RecordFieldType.INT.getDataType()), new RecordField("boolean", RecordFieldType.BOOLEAN.getDataType())));
    SimpleRecordSchema recordSchema2 = new SimpleRecordSchema(Arrays.asList(new RecordField("integer", RecordFieldType.INT.getDataType()), new RecordField("string", RecordFieldType.STRING.getDataType())));
    RecordSchema recordChoiceSchema = new SimpleRecordSchema(Collections.singletonList(new RecordField("record", RecordFieldType.CHOICE.getChoiceDataType(RecordFieldType.ARRAY.getArrayDataType(RecordFieldType.RECORD.getRecordDataType(recordSchema1)), RecordFieldType.ARRAY.getArrayDataType(RecordFieldType.RECORD.getRecordDataType(recordSchema2))))));
    RecordSchema schema = new SimpleRecordSchema(Collections.singletonList(new RecordField("dataCollection", RecordFieldType.ARRAY.getArrayDataType(RecordFieldType.RECORD.getRecordDataType(recordChoiceSchema)))));
    SimpleRecordSchema expectedChildSchema1 = new SimpleRecordSchema(Arrays.asList(new RecordField("integer", RecordFieldType.INT.getDataType()), new RecordField("boolean", RecordFieldType.BOOLEAN.getDataType())));
    SimpleRecordSchema expectedChildSchema2 = new SimpleRecordSchema(Arrays.asList(new RecordField("integer", RecordFieldType.INT.getDataType()), new RecordField("string", RecordFieldType.STRING.getDataType())));
    RecordSchema expectedRecordChoiceSchema = new SimpleRecordSchema(Collections.singletonList(new RecordField("record", RecordFieldType.CHOICE.getChoiceDataType(RecordFieldType.ARRAY.getArrayDataType(RecordFieldType.RECORD.getRecordDataType(expectedChildSchema1)), RecordFieldType.ARRAY.getArrayDataType(RecordFieldType.RECORD.getRecordDataType(expectedChildSchema2))))));
    // Since the actual arrays have records with either (INT, BOOLEAN, STRING) or (INT, STRING, STRING)
    //  while the explicit schema defines only (INT, BOOLEAN) and (INT, STRING) we can't tell which record schema to chose
    //  so we take the first one (INT, BOOLEAN) - as best effort - for both cases
    List<Object> expected = Arrays.asList(new MapRecord(expectedRecordChoiceSchema, new HashMap<>() {

        {
            put("record", new Object[] { new MapRecord(expectedChildSchema1, new HashMap<>() {

                {
                    put("integer", 11);
                    put("boolean", true);
                    put("extraString", "extraStringValue11");
                }
            }), new MapRecord(expectedChildSchema1, new HashMap<>() {

                {
                    put("integer", 12);
                    put("boolean", false);
                    put("extraString", "extraStringValue12");
                }
            }) });
        }
    }), new MapRecord(expectedRecordChoiceSchema, new HashMap<>() {

        {
            put("record", new Object[] { new MapRecord(expectedChildSchema1, new HashMap<>() {

                {
                    put("integer", 21);
                    put("extraString", "extraStringValue21");
                    put("string", "stringValue21");
                }
            }), new MapRecord(expectedChildSchema1, new HashMap<>() {

                {
                    put("integer", 22);
                    put("extraString", "extraStringValue22");
                    put("string", "stringValue22");
                }
            }) });
        }
    }));
    testReadRecords(yamlPath, schema, expected);
}

