public void testNoRevisions() {
    // Create a bucket...
    final Bucket bucket = new Bucket();
    bucket.setName("Integration Test Bucket");
    bucket.setDescription("A bucket created by an integration test.");
    final Bucket createdBucket = client.target(createURL("buckets")).request().post(Entity.entity(bucket, MediaType.APPLICATION_JSON), Bucket.class);
    assertBucketsEqual(bucket, createdBucket, false);
    assertNotNull(createdBucket.getIdentifier());
    // Update bucket...
    createdBucket.setName("Renamed Bucket");
    createdBucket.setDescription("This bucket has been updated by an integration test.");
    final Bucket updatedBucket = client.target(createURL("buckets/" + createdBucket.getIdentifier())).request().put(Entity.entity(createdBucket, MediaType.APPLICATION_JSON), Bucket.class);
    assertBucketsEqual(updatedBucket, createdBucket, true);
    // Create a flow...
    final VersionedFlow flow = new VersionedFlow();
    // Simulate NiFi sending an identifier
    flow.setIdentifier(UUID.randomUUID().toString());
    flow.setBucketIdentifier(createdBucket.getIdentifier());
    flow.setName("Test Flow");
    flow.setDescription("This is a flow created by an integration test.");
    final VersionedFlow createdFlow = client.target(createURL("buckets/{bucketId}/flows")).resolveTemplate("bucketId", flow.getBucketIdentifier()).request().post(Entity.entity(flow, MediaType.APPLICATION_JSON), VersionedFlow.class);
    assertFlowsEqual(flow, createdFlow, false);
    assertNotNull(createdFlow.getIdentifier());
    // Update flow...
    createdFlow.setName("Renamed Flow");
    createdFlow.setDescription("This flow has been updated by an integration test.");
    final VersionedFlow updatedFlow = client.target(createURL("buckets/{bucketId}/flows/{flowId}")).resolveTemplate("bucketId", flow.getBucketIdentifier()).resolveTemplate("flowId", createdFlow.getIdentifier()).request().put(Entity.entity(createdFlow, MediaType.APPLICATION_JSON), VersionedFlow.class);
    assertTrue(updatedFlow.getModifiedTimestamp() > createdFlow.getModifiedTimestamp());
    // Create a version of a flow...
    final VersionedFlowSnapshotMetadata flowSnapshotMetadata = new VersionedFlowSnapshotMetadata();
    flowSnapshotMetadata.setVersion(1);
    flowSnapshotMetadata.setBucketIdentifier(createdFlow.getBucketIdentifier());
    flowSnapshotMetadata.setFlowIdentifier(createdFlow.getIdentifier());
    flowSnapshotMetadata.setComments("This is snapshot 1, created by an integration test.");
    final VersionedFlowSnapshot flowSnapshot = new VersionedFlowSnapshot();
    flowSnapshot.setSnapshotMetadata(flowSnapshotMetadata);
    // an empty root process group
    flowSnapshot.setFlowContents(new VersionedProcessGroup());
    final VersionedFlowSnapshot createdFlowSnapshot = client.target(createURL("buckets/{bucketId}/flows/{flowId}/versions")).resolveTemplate("bucketId", flowSnapshotMetadata.getBucketIdentifier()).resolveTemplate("flowId", flowSnapshotMetadata.getFlowIdentifier()).request().post(Entity.entity(flowSnapshot, MediaType.APPLICATION_JSON), VersionedFlowSnapshot.class);
    assertFlowSnapshotsEqual(flowSnapshot, createdFlowSnapshot, false);
    // Delete flow...
    final VersionedFlow deletedFlow = client.target(createURL("buckets/{bucketId}/flows/{flowId}")).resolveTemplate("bucketId", createdFlow.getBucketIdentifier()).resolveTemplate("flowId", createdFlow.getIdentifier()).request().delete(VersionedFlow.class);
    assertNotNull(deletedFlow);
    // Delete bucket...
    final Bucket deletedBucket = client.target(createURL("buckets/" + createdBucket.getIdentifier())).request().delete(Bucket.class);
    assertNotNull(deletedBucket);
}

