@Test
public void testParseParameterOverride() {
    final BootstrapConfiguration configuration = BootstrapConfiguration.fromCommandLineArgs(new String[] { "-e", engineConfigPropertiesFilename, "-f", engineConfigPropertiesFilename });
    // simple case, context name, param name, param value, no special chars
    testOverride(configuration, "a:b=c", "a", "b", "c");
    // test no context name
    testOverride(configuration, "a=b", null, "a", "b");
    // test escaped colon in context name
    testOverride(configuration, "a\\:b:c=d", "a:b", "c", "d");
    // test colon in param name
    testOverride(configuration, "a:b:c=d", "a", "b:c", "d");
    // test colon in param value
    testOverride(configuration, "a=b:c", null, "a", "b:c");
    // test equals in param value
    testOverride(configuration, "a=b=c", null, "a", "b=c");
    // test spaces
    testOverride(configuration, "a b:c d=e f g", "a b", "c d", "e f g");
    // Any input that doesn't contain an equals should fail
    testParseFailure(configuration, "a");
    testParseFailure(configuration, "a:b");
    testParseFailure(configuration, "a:b:c");
    testParseFailure(configuration, "=c");
}

