@Test
public void testPollingForBatch() {
    final StatelessFlowFileQueue queue = new StatelessFlowFileQueue("id");
    for (int i = 0; i < 100; i++) {
        queue.put(new MockFlowFile(i));
    }
    assertQueueSize(100, 0, queue.size());
    for (int i = 0; i < 10; i++) {
        final List<FlowFileRecord> flowFiles = queue.poll(10, Collections.emptySet());
        assertEquals(10, flowFiles.size());
        assertQueueSize(100 - 10 * i, 0, queue.size());
        queue.acknowledge(flowFiles);
        assertQueueSize(100 - 10 * (i + 1), 0, queue.size());
        int batchIndex = 0;
        for (final FlowFileRecord flowFile : flowFiles) {
            assertEquals(i * 10 + batchIndex, flowFile.getId());
            batchIndex++;
        }
    }
    assertTrue(queue.isEmpty());
    assertNull(queue.poll(Collections.emptySet()));
}

@Test
public void testPollWithFilter() {
    final StatelessFlowFileQueue queue = new StatelessFlowFileQueue("id");
    for (int i = 0; i < 100; i++) {
        queue.put(new MockFlowFile(i));
    }
    assertQueueSize(100, 0, queue.size());
    // Poll for a single FlowFile in the middle.
    final List<FlowFileRecord> matching = queue.poll(ff -> ff.getId() == 50 ? FlowFileFilter.FlowFileFilterResult.ACCEPT_AND_TERMINATE : FlowFileFilter.FlowFileFilterResult.REJECT_AND_CONTINUE, Collections.emptySet());
    assertEquals(1, matching.size());
    assertEquals(50, matching.get(0).getId());
    queue.acknowledge(matching.get(0));
    assertQueueSize(99, 0, queue.size());
    final List<FlowFileRecord> allBut40 = queue.poll(ff -> ff.getId() == 40 ? FlowFileFilter.FlowFileFilterResult.REJECT_AND_CONTINUE : FlowFileFilter.FlowFileFilterResult.ACCEPT_AND_CONTINUE, Collections.emptySet());
    assertEquals(98, allBut40.size());
    queue.acknowledge(allBut40);
    assertQueueSize(1, 0, queue.size());
    for (final FlowFileRecord flowFile : allBut40) {
        assertNotEquals(40, flowFile.getId());
    }
}

@Test
public void testWriteThenRead() throws IOException {
    final byte[] contents = "Hello, World!".getBytes();
    final ContentClaim claim = repository.create(true);
    try (final OutputStream out = repository.write(claim)) {
        out.write(contents);
    }
    assertEquals(contents.length, claim.getLength());
    // Ensure we can read multiple times.
    for (int i = 0; i < 5; i++) {
        final byte[] bytesRead;
        try (final InputStream in = repository.read(claim);
            final ByteArrayOutputStream baos = new ByteArrayOutputStream()) {
            StreamUtils.copy(in, baos);
            bytesRead = baos.toByteArray();
        }
        assertEquals(new String(contents), new String(bytesRead));
    }
    File[] files = repoDirectory.listFiles();
    assertNotNull(files);
    assertEquals(1, files.length);
    repository.purge();
    files = repoDirectory.listFiles();
    assertNotNull(files);
    assertEquals(0, files.length);
}

@Test
public void testOverwriteFails() throws IOException {
    final byte[] contents = "Hello, World!".getBytes();
    final ContentClaim claim = repository.create(true);
    try (final OutputStream out = repository.write(claim)) {
        out.write(contents);
    }
    // An attempt to write to a content claim multiple times should fail
    assertThrows(IOException.class, () -> repository.write(claim));
}

