@Test
public void testSingleNodeStrategy() throws NiFiClientException, IOException, InterruptedException {
    final ProcessorEntity generate = getClientUtil().createProcessor("GenerateFlowFile");
    final ProcessorEntity count = getClientUtil().createProcessor("CountEvents");
    final ConnectionEntity connection = getClientUtil().createConnection(generate, count, "success");
    getClientUtil().setAutoTerminatedRelationships(count, "success");
    // Configure Processor to generate 10 FlowFiles, each 1 MB, on each node, for a total of 20 FlowFiles.
    final Map<String, String> generateProperties = new HashMap<>();
    generateProperties.put("File Size", "1 MB");
    generateProperties.put("Batch Size", "10");
    getClientUtil().updateProcessorProperties(generate, generateProperties);
    // Round Robin between nodes. This should result in 10 FlowFiles on each node.
    getClientUtil().updateConnectionLoadBalancing(connection, LoadBalanceStrategy.SINGLE_NODE, LoadBalanceCompression.DO_NOT_COMPRESS, null);
    // Generate the data.
    getClientUtil().startProcessor(generate);
    // Wait until all 20 FlowFiles are queued up.
    waitFor(() -> {
        final ConnectionStatusEntity statusEntity = getConnectionStatus(connection.getId());
        return statusEntity.getConnectionStatus().getAggregateSnapshot().getFlowFilesQueued() == 20;
    });
    // Wait until load balancing is complete
    waitFor(() -> isConnectionDoneLoadBalancing(connection.getId()));
    // Ensure that all FlowFiles are on the same node.
    final ConnectionStatusEntity statusEntity = getConnectionStatus(connection.getId());
    final ConnectionStatusDTO connectionStatusDto = statusEntity.getConnectionStatus();
    final int numNodes = connectionStatusDto.getNodeSnapshots().size();
    int emptyNodes = 0;
    for (final NodeConnectionStatusSnapshotDTO nodeStatusDto : connectionStatusDto.getNodeSnapshots()) {
        final ConnectionStatusSnapshotDTO snapshotDto = nodeStatusDto.getStatusSnapshot();
        final int flowFilesQueued = snapshotDto.getFlowFilesQueued();
        // Number of flowfiles should either be 0 or should be equal to the total number of FlowFiles in the queue.
        if (flowFilesQueued == 0) {
            emptyNodes++;
        } else {
            assertEquals(statusEntity.getConnectionStatus().getAggregateSnapshot().getFlowFilesQueued().intValue(), flowFilesQueued);
        }
    }
    // Number of empty nodes should be one less than total number of nodes.
    assertEquals(numNodes - 1, emptyNodes);
}

@Test
public void testPartitionByAttribute() throws NiFiClientException, IOException, InterruptedException {
    final ProcessorEntity generate = getClientUtil().createProcessor("GenerateFlowFile");
    final ProcessorEntity count = getClientUtil().createProcessor("CountEvents");
    final ConnectionEntity connection = getClientUtil().createConnection(generate, count, "success");
    getClientUtil().setAutoTerminatedRelationships(count, "success");
    // Configure Processor to generate 10 FlowFiles, each 1 MB, on each node, for a total of 20 FlowFiles.
    final Map<String, String> generateProperties = new HashMap<>();
    generateProperties.put("File Size", "1 MB");
    generateProperties.put("Batch Size", "10");
    generateProperties.put("number", "0");
    getClientUtil().updateProcessorProperties(generate, generateProperties);
    getClientUtil().updateProcessorExecutionNode(generate, ExecutionNode.PRIMARY);
    // Round Robin between nodes. This should result in 10 FlowFiles on each node.
    getClientUtil().updateConnectionLoadBalancing(connection, LoadBalanceStrategy.PARTITION_BY_ATTRIBUTE, LoadBalanceCompression.DO_NOT_COMPRESS, "number");
    // Queue 100 FlowFiles. 10 with number=0, 10 with number=1, 10 with number=2, etc. to up 10 with number=9
    for (int i = 1; i <= 10; i++) {
        // Generate the data.
        getClientUtil().startProcessor(generate);
        final int expectedQueueSize = 10 * i;
        // Wait until all 10 FlowFiles are queued up.
        waitFor(() -> {
            final ConnectionStatusEntity statusEntity = getConnectionStatus(connection.getId());
            return statusEntity.getConnectionStatus().getAggregateSnapshot().getFlowFilesQueued() == expectedQueueSize;
        });
        getNifiClient().getProcessorClient().stopProcessor(generate);
        getClientUtil().waitForStoppedProcessor(generate.getId());
        generateProperties.put("number", String.valueOf(i));
        getClientUtil().updateProcessorProperties(generate, generateProperties);
    }
    // Wait until load balancing is complete
    waitFor(() -> isConnectionDoneLoadBalancing(connection.getId()));
    final Map<String, Set<String>> nodesByAttribute = new HashMap<>();
    for (int i = 0; i < 100; i++) {
        final FlowFileEntity flowFile = getClientUtil().getQueueFlowFile(connection.getId(), i);
        final String numberValue = flowFile.getFlowFile().getAttributes().get("number");
        final Set<String> nodes = nodesByAttribute.computeIfAbsent(numberValue, key -> new HashSet<>());
        nodes.add(flowFile.getFlowFile().getClusterNodeId());
    }
    assertEquals(10, nodesByAttribute.size());
    for (final Map.Entry<String, Set<String>> entry : nodesByAttribute.entrySet()) {
        final Set<String> nodes = entry.getValue();
        assertEquals(1, nodes.size(), "FlowFile with attribute number=" + entry.getKey() + " went to nodes " + nodes);
    }
}

@Test
public void testOffload() throws NiFiClientException, IOException, InterruptedException {
    final ProcessorEntity generate = getClientUtil().createProcessor("GenerateFlowFile");
    final ProcessorEntity count = getClientUtil().createProcessor("CountEvents");
    final ConnectionEntity connection = getClientUtil().createConnection(generate, count, "success");
    getClientUtil().setAutoTerminatedRelationships(count, "success");
    // Configure Processor to generate 10 FlowFiles, each 1 MB, on each node (for a total of 20)
    final Map<String, String> generateProperties = new HashMap<>();
    generateProperties.put("File Size", "1 MB");
    generateProperties.put("Batch Size", "10");
    getClientUtil().updateProcessorProperties(generate, generateProperties);
    // Generate the data.
    getClientUtil().startProcessor(generate);
    // Wait until all 20 FlowFiles are queued up.
    waitFor(() -> {
        final ConnectionStatusEntity statusEntity = getConnectionStatus(connection.getId());
        return statusEntity.getConnectionStatus().getAggregateSnapshot().getFlowFilesQueued() == 20;
    });
    final ClusterEntity clusterEntity = getNifiClient().getControllerClient().getNodes();
    final Collection<NodeDTO> nodes = clusterEntity.getCluster().getNodes();
    // Do not disconnect the node that the client is pointing out
    final NodeDTO firstNodeDto = nodes.stream().filter(nodeDto -> nodeDto.getApiPort() != 5671).findFirst().get();
    final String nodeId = firstNodeDto.getNodeId();
    getClientUtil().disconnectNode(nodeId);
    waitForNodeStatus(firstNodeDto, "DISCONNECTED");
    getClientUtil().offloadNode(nodeId);
    waitForNodeStatus(firstNodeDto, "OFFLOADED");
    assertEquals(20, getQueueSize(connection.getId()));
    assertEquals(20 * 1024 * 1024, getQueueBytes(connection.getId()));
    getClientUtil().connectNode(nodeId);
    waitForAllNodesConnected();
    // The node that was disconnected will have stopped its processor when it was told to offload. When it joins back into the cluster,
    // the node will determine that the cluster wants the GenerateFlowFile processor running and as a result start the Processor again. This will
    // Trigger the processor to then generate another batch of 10 FlowFiles.
    waitFor(() -> getQueueSize(connection.getId()) == 30);
    assertEquals(30 * 1024 * 1024, getQueueBytes(connection.getId()));
}

@Test
public void testRoundRobinWithRestartAndPortChange() throws NiFiClientException, IOException, InterruptedException {
    ProcessorEntity generate = getClientUtil().createProcessor("GenerateFlowFile");
    final ProcessorEntity count = getClientUtil().createProcessor("CountEvents");
    final ConnectionEntity connection = getClientUtil().createConnection(generate, count, "success");
    getClientUtil().setAutoTerminatedRelationships(count, "success");
    // Configure Processor to generate 20 FlowFiles, each 1 MB and run on Primary Node.
    final Map<String, String> generateProperties = new HashMap<>();
    generateProperties.put("File Size", "1 MB");
    generateProperties.put("Batch Size", "20");
    getClientUtil().updateProcessorProperties(generate, generateProperties);
    getClientUtil().updateProcessorExecutionNode(generate, ExecutionNode.PRIMARY);
    // Round Robin between nodes. This should result in 10 FlowFiles on each node.
    getClientUtil().updateConnectionLoadBalancing(connection, LoadBalanceStrategy.ROUND_ROBIN, LoadBalanceCompression.DO_NOT_COMPRESS, null);
    // Generate the data.
    getClientUtil().startProcessor(generate);
    // Wait until all 20 FlowFiles are queued up.
    waitFor(() -> {
        final ConnectionStatusEntity statusEntity = getConnectionStatus(connection.getId());
        return statusEntity.getConnectionStatus().getAggregateSnapshot().getFlowFilesQueued() == 20;
    });
    // Wait until load balancing is complete
    waitFor(() -> isConnectionDoneLoadBalancing(connection.getId()));
    // Ensure that the FlowFiles are evenly distributed between the nodes.
    final ConnectionStatusEntity statusEntity = getConnectionStatus(connection.getId());
    assertTrue(isEvenlyDistributed(statusEntity));
    assertEquals(20, getQueueSize(connection.getId()));
    assertEquals(20 * 1024 * 1024, getQueueBytes(connection.getId()));
    getNifiClient().getProcessorClient().stopProcessor(generate);
    // Empty the queue because on restart, Node 2 will rebalance all of its data using the Load-Balance strategy, and we don't want
    // the data to start out lopsided.
    getClientUtil().emptyQueue(connection.getId());
    final NiFiInstance instance2 = this.getNiFiInstance().getNodeInstance(2);
    instance2.stop();
    final Map<String, String> updatedLoadBalanceProperties = new HashMap<>();
    updatedLoadBalanceProperties.put("nifi.cluster.load.balance.host", "127.0.0.1");
    updatedLoadBalanceProperties.put("nifi.cluster.load.balance.port", "7676");
    instance2.setProperties(updatedLoadBalanceProperties);
    instance2.start(true);
    waitForAllNodesConnected();
    generate = getNifiClient().getProcessorClient().getProcessor(generate.getId());
    // Generate data and wait for it to be spread across the cluster. We do this in an infinite while() loop because
    // there can be a failure, in which case we'll retry. If that happens, we just want to keep retrying until the test
    // times out.
    while (true) {
        // Generate the data.
        getClientUtil().startProcessor(generate);
        // Wait until all 20 FlowFiles are queued up
        waitFor(() -> {
            final ConnectionStatusEntity secondRoundStatusEntity = getConnectionStatus(connection.getId());
            return secondRoundStatusEntity.getConnectionStatus().getAggregateSnapshot().getFlowFilesQueued() == 20;
        });
        // Wait until load balancing is complete
        waitFor(() -> isConnectionDoneLoadBalancing(connection.getId()));
        // Log the distribution of data between nodes for easier troubleshooting in case there's a failure.
        final ConnectionStatusEntity afterSecondDataGenerationStatusEntity = getConnectionStatus(connection.getId());
        final List<NodeConnectionStatusSnapshotDTO> nodeSnapshots = afterSecondDataGenerationStatusEntity.getConnectionStatus().getNodeSnapshots();
        logger.info("FlowFiles Queued Per Node:");
        nodeSnapshots.forEach(snapshot -> logger.info("{}:{} - {}", snapshot.getAddress(), snapshot.getApiPort(), snapshot.getStatusSnapshot().getFlowFilesQueued()));
        // Check if the FlowFiles are evenly distributed between the nodes. If so, we're done.
        final boolean evenlyDistributed = isEvenlyDistributed(afterSecondDataGenerationStatusEntity);
        if (evenlyDistributed) {
            break;
        }
        // If there's an IOException thrown while communicating between the nodes, the data will be rebalanced and will go to
        // the local partition. There's nothing we can do about that in this test. However, we can verify that NiFi recovers
        // from this and continues to distribute data. To do that, we will stop the processor so that it can be started again
        // (and produce more data) and we can empty the queue so that we know how much data to expect.
        getNifiClient().getProcessorClient().stopProcessor(generate);
        getClientUtil().emptyQueue(connection.getId());
    }
    assertEquals(20, getQueueSize(connection.getId()));
    assertEquals(20 * 1024 * 1024, getQueueBytes(connection.getId()));
}

@Test
public void testControllerServiceCreated() throws NiFiClientException, IOException {
    final ProcessGroupEntity group1 = getClientUtil().createProcessGroup("Group 1", "root");
    final ProcessGroupEntity group2 = getClientUtil().createProcessGroup("Group 2", "root");
    final ProcessorEntity proc1 = getClientUtil().createProcessor("MigrateProperties", group1.getId());
    final ProcessorEntity proc2 = getClientUtil().createProcessor("MigrateProperties", group1.getId());
    final ProcessorEntity proc3 = getClientUtil().createProcessor("MigrateProperties", group1.getId());
    final ProcessorEntity proc4 = getClientUtil().createProcessor("MigrateProperties", group2.getId());
    // Update proc1 and proc2 with the same values.
    // Set same values for proc4, which is in a different group.
    final Map<String, String> proc1Properties = Map.of("attr-to-add", "greeting", "attr-value", "Hi", "ignored", "17");
    getClientUtil().updateProcessorProperties(proc1, proc1Properties);
    getClientUtil().updateProcessorProperties(proc2, proc1Properties);
    getClientUtil().updateProcessorProperties(proc4, proc1Properties);
    final Map<String, String> proc3Properties = new HashMap<>(proc1Properties);
    proc3Properties.put("ignored", "41");
    getClientUtil().updateProcessorProperties(proc3, proc3Properties);
    // Stop NiFi, switch out the system-tests-extensions nar for the alternate-config-nar, and restart
    getNiFiInstance().stop();
    switchOutNars();
    getNiFiInstance().start(true);
    // Procs 1 and 2 should have the same value for the Controller Service.
    // Procs 3 and 4 should each have different values
    final ControllerServicesClient serviceClient = getNifiClient().getControllerServicesClient();
    final Map<String, String> proc1UpdatedProps = getProperties(proc1);
    final Map<String, String> proc2UpdatedProps = getProperties(proc2);
    final Map<String, String> proc3UpdatedProps = getProperties(proc3);
    final Map<String, String> proc4UpdatedProps = getProperties(proc4);
    final Set<String> serviceIds = new HashSet<>();
    for (final Map<String, String> propertiesMap : List.of(proc1UpdatedProps, proc2UpdatedProps, proc3UpdatedProps, proc4UpdatedProps)) {
        final String serviceId = propertiesMap.get(SERVICE);
        assertNotNull(serviceId);
        serviceIds.add(serviceId);
    }
    // Should be 3 different services
    assertEquals(3, serviceIds.size());
    // Procs 1 and 2 should reference the same service.
    assertEquals(proc1UpdatedProps.get(SERVICE), proc2UpdatedProps.get(SERVICE));
    // Services for procs 1-3 should be in group 1
    for (final String serviceId : List.of(proc1UpdatedProps.get(SERVICE), proc2UpdatedProps.get(SERVICE), proc3UpdatedProps.get(SERVICE))) {
        assertEquals(group1.getId(), serviceClient.getControllerService(serviceId).getParentGroupId());
    }
    // Service for proc 4 should be in group 2
    assertEquals(group2.getId(), serviceClient.getControllerService(proc4UpdatedProps.get(SERVICE)).getParentGroupId());
    // Ensure that the service's properties were also migrated, since the processor mapped the "ignored" value to the old property name of the service.
    final ControllerServiceEntity service1 = serviceClient.getControllerService(proc1UpdatedProps.get(SERVICE));
    final Map<String, String> service1Props = service1.getComponent().getProperties();
    assertEquals(Map.of("Initial Value", "17"), service1Props);
    assertEquals(2, service1.getComponent().getReferencingComponents().size());
    final ControllerServiceEntity service4 = serviceClient.getControllerService(proc4UpdatedProps.get(SERVICE));
    final Map<String, String> service4Props = service4.getComponent().getProperties();
    assertEquals(Map.of("Initial Value", "17"), service4Props);
    assertEquals(1, service4.getComponent().getReferencingComponents().size());
    final ControllerServiceEntity service3 = serviceClient.getControllerService(proc3UpdatedProps.get(SERVICE));
    final Map<String, String> service3Props = service3.getComponent().getProperties();
    assertEquals(Map.of("Initial Value", "41"), service3Props);
    assertEquals(1, service3.getComponent().getReferencingComponents().size());
}

@Test
public void testPropertyMigration() throws NiFiClientException, IOException {
    final ProcessorEntity migrate = getClientUtil().createProcessor("MigrateProperties");
    final Map<String, String> properties = migrate.getComponent().getConfig().getProperties();
    final Map<String, String> expectedProperties = new HashMap<>();
    expectedProperties.put("ingest-data", "true");
    expectedProperties.put("attr-to-add", null);
    expectedProperties.put("attr-value", null);
    expectedProperties.put("ignored", null);
    assertEquals(expectedProperties, properties);
    getClientUtil().updateProcessorProperties(migrate, Collections.singletonMap("attr-to-add", "greeting"));
    getClientUtil().updateProcessorProperties(migrate, Collections.singletonMap("attr-value", "Hi"));
    getClientUtil().updateProcessorProperties(migrate, Collections.singletonMap("ignored", "This is ignored"));
    final ProcessorEntity terminate = getClientUtil().createProcessor("TerminateFlowFile");
    final ConnectionEntity connection = getClientUtil().createConnection(migrate, terminate, "success");
    getClientUtil().setAutoTerminatedRelationships(migrate, "failure");
    getClientUtil().setRetriedRelationships(migrate, "success");
    // Create Controller Services. Make the first depend on the second
    final ControllerServiceEntity firstService = getClientUtil().createControllerService("MigrationService");
    final ControllerServiceEntity secondService = getClientUtil().createControllerService("MigrationService");
    getClientUtil().updateControllerServiceProperties(firstService, Map.of("Start", "5", "Dependent Service", secondService.getId()));
    // Ensure that the reference count is correct
    final ControllerServicesClient servicesClient = getNifiClient().getControllerServicesClient();
    assertEquals(1, servicesClient.getControllerService(secondService.getId()).getComponent().getReferencingComponents().size());
    // Create a Reporting Task and set its properties
    final ReportingTaskEntity reportingTask = getClientUtil().createReportingTask("MigrationReportingTask");
    getClientUtil().updateReportingTaskProperties(reportingTask, Map.of("Start", "15", "Invalid Property", "Invalid"));
    // Stop NiFi, switch out the system-tests-extensions nar for the alternate-config-nar, and restart
    getNiFiInstance().stop();
    switchOutNars();
    getNiFiInstance().start(true);
    // Ensure that the Processor's config was properly updated
    final ProcessorEntity updated = getNifiClient().getProcessorClient().getProcessor(migrate.getId());
    final Map<String, String> updatedProperties = updated.getComponent().getConfig().getProperties();
    final Map<String, String> expectedUpdatedProperties = new HashMap<>();
    expectedUpdatedProperties.put("Ingest Data", "true");
    expectedUpdatedProperties.put("Attribute to add", "greeting");
    expectedUpdatedProperties.put("Attribute Value", "Hi");
    expectedUpdatedProperties.put("New Property", "true");
    expectedUpdatedProperties.put("Service", null);
    assertEquals(expectedUpdatedProperties, updatedProperties);
    final ProcessorConfigDTO updatedConfig = updated.getComponent().getConfig();
    assertEquals(Set.of("even", "odd"), updatedConfig.getRetriedRelationships());
    assertEquals(Set.of("broken"), updatedConfig.getAutoTerminatedRelationships());
    // Ensure that outgoing connections were properly updated
    final ConnectionEntity updatedConnection = getNifiClient().getConnectionClient().getConnection(connection.getId());
    final Set<String> selectedRelationships = updatedConnection.getComponent().getSelectedRelationships();
    assertEquals(Set.of("even", "odd"), selectedRelationships);
    // Ensure that the first Controller Service was properly updated and that its reference to the second service is properly handled.
    // I.e., the second service should no longer have any references.
    final ControllerServiceEntity updatedFirstService = servicesClient.getControllerService(firstService.getId());
    final Map<String, String> expectedServicesProperties = Map.of("Initial Value", "5");
    assertEquals(expectedServicesProperties, updatedFirstService.getComponent().getProperties());
    final ControllerServiceEntity updatedSecondService = servicesClient.getControllerService(secondService.getId());
    assertTrue(updatedSecondService.getComponent().getReferencingComponents().isEmpty());
    // Ensure that the Reporting Task was properly updated
    final ReportingTaskEntity updatedReportingTask = getNifiClient().getReportingTasksClient().getReportingTask(reportingTask.getId());
    final Map<String, String> expectedReportingTaskProperties = Map.of("Initial Value", "15", "Invalid Property", "Invalid");
    assertEquals(expectedReportingTaskProperties, updatedReportingTask.getComponent().getProperties());
}

