        try {
            final boolean correctSize = file.exists() && file.length() == customText.length();
            if (!correctSize) {
                return false;
            }
            final List<String> lines = Files.readAllLines(file.toPath());
            if (lines.size() != 1) {
                return false;
            }
            return customText.equals(lines.get(0));
        } catch (final Exception e) {
            return false;
        }
    });
}

