    final Path outputLoginIdentityProvidersPath = tempDir.resolve(LOGIN_IDENTITY_PROVIDERS_TRANSFORMED);
    final String[] arguments = { "-m", "-e", BOOTSTRAP_HEXADECIMAL_KEY, "-H", STANDARD_PROTECTION_SCHEME, "-k", NEW_BOOTSTRAP_HEXADECIMAL_KEY, "-l", loginIdentityProvidersPath.toString(), "-i", outputLoginIdentityProvidersPath.toString() };
    final int status = run(arguments);
    assertEquals(CommandLine.ExitCode.OK, status);
    assertEncryptedPropertyFound(outputLoginIdentityProvidersPath);
}

@Test
void testGetDerivedKeyEncoded() {
    final StandardDerivedKeyGenerator generator = new StandardDerivedKeyGenerator();
    final char[] random = UUID.randomUUID().toString().toCharArray();
    final String firstDerivedKey = generator.getDerivedKeyEncoded(random);
    final String secondDerivedKey = generator.getDerivedKeyEncoded(random);
    assertEquals(firstDerivedKey, secondDerivedKey);
    final byte[] decoded = HexFormat.of().parseHex(firstDerivedKey);
    assertEquals(KEY_LENGTH, decoded.length);
}

@Test
void testTransformUnprotectedProperty() throws URISyntaxException, IOException {
    final Path propertiesPath = getResourcePath(UNPROTECTED_NIFI_PROPERTIES);
    final Path tempPropertiesPath = tempDir.resolve(propertiesPath.getFileName());
    Files.copy(propertiesPath, tempPropertiesPath);
    final Path outputPropertiesPath = tempDir.resolve(PROPERTIES_TRANSFORMED);
    final ApplicationProperties applicationProperties = new ApplicationProperties(Collections.emptyMap());
    final FileTransformer transformer = new ApplicationPropertiesFileTransformer(applicationProperties, sensitivePropertyProvider, SENSITIVE_PROPERTY_NAMES);
    when(sensitivePropertyProvider.getIdentifierKey()).thenReturn(PROVIDER_IDENTIFIER_KEY);
    when(sensitivePropertyProvider.protect(eq(UNPROTECTED), any())).thenReturn(ENCRYPTED);
    transformer.transform(tempPropertiesPath, outputPropertiesPath);
    assertProtectedPropertyFound(outputPropertiesPath);
}

